CREATE TABLE churn_notifications (user_id VARCHAR PRIMARY KEY, risk_level VARCHAR, days_since_login INTEGER, engagement_level NUMERIC);
WITH fan_data AS (
    SELECT f.userregistry, pa.lastlogdt, e.engrate, r.churnflag, (1 - pa.intconsist) * 2 + (('2025-04-20'::date - pa.lastlogdt) / 30.0 * 0.5 + CAST((CASE WHEN r.churnflag = 'None' THEN 0 WHEN r.churnflag = 'Low' THEN 1 WHEN r.churnflag = 'Medium' THEN 2 WHEN r.churnflag = 'High' THEN 3 ELSE 0 END) AS numeric) / 3.0 * 2) as rrf_val FROM retentionandinfluence r JOIN engagement e ON r.retainengagepivot = e.engagereg JOIN membershipandspending m ON e.engagememberpivot = m.memberreg JOIN fans f ON m.memberfanpivot = f.userregistry JOIN preferencesandsettings pa ON m.memberreg = pa.preferencesmemberpivot WHERE (1 - pa.intconsist) * 2 + (('2025-04-20'::date - pa.lastlogdt) / 30.0 * 0.5 + CAST((CASE WHEN r.churnflag = 'None' THEN 0 WHEN r.churnflag = 'Low' THEN 1 WHEN r.churnflag = 'Medium' THEN 2 WHEN r.churnflag = 'High' THEN 3 ELSE 0 END) AS numeric) / 3.0 * 2) > 2.5
), ranked AS (
    SELECT *, ROW_NUMBER() OVER (PARTITION BY userregistry ORDER BY rrf_val DESC) as rn FROM fan_data
)
INSERT INTO churn_notifications SELECT userregistry, CASE WHEN rrf_val > 4.5 THEN 'Severe' WHEN rrf_val >= 3.5 AND rrf_val <= 4.5 THEN 'High' ELSE 'Medium' END, ('2025-04-20'::date - lastlogdt), engrate FROM ranked WHERE rn = 1;

